import 'dart:io' show Platform;

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

/// Short sound effects (bundled WAVs generated by tool/gen_sounds.dart).
class SoundService {
  SoundService();
  AudioPlayer? _player;

  Future<void> play(String name, {required bool enabled}) async {
    if (!enabled) return;
    try {
      _player ??= AudioPlayer()..setReleaseMode(ReleaseMode.stop);
      await _player!.stop();
      await _player!.play(AssetSource('sounds/$name.wav'));
    } catch (e) {
      debugPrint('sound failed: $e');
    }
  }
}

class Haptics {
  static Future<void> buzz({required bool enabled}) async {
    if (!enabled) return;
    try {
      await HapticFeedback.heavyImpact();
      await Future<void>.delayed(const Duration(milliseconds: 120));
      await HapticFeedback.heavyImpact();
    } catch (_) {}
  }

  static Future<void> tick({required bool enabled}) async {
    if (!enabled) return;
    try {
      await HapticFeedback.selectionClick();
    } catch (_) {}
  }
}

/// Blocks screenshots/recents previews on Android while secret cards are
/// visible (FLAG_SECURE via a method channel in MainActivity).
class SecureScreen {
  static const _channel = MethodChannel('hushbug/secure');

  static Future<void> set(bool secure) async {
    if (kIsWeb || !Platform.isAndroid) return;
    try {
      await _channel.invokeMethod<void>(secure ? 'enable' : 'disable');
    } catch (_) {}
  }
}
